  ('hls-sec-048', 'Security, Compliance, and Identity on Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Beginner', 20, 'English', 'https://learn.microsoft.com/en-us/training/topics/sci', 'free', 'Public Microsoft Learn catalogue; no login required to browse.', 'learning_path', 'Microsoft Learn''s curated catalogue of security, compliance and identity learning paths covering the SC-900 family and role-based certifications.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-049', 'Security hub - Security | Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Intermediate', 16, 'English', 'https://learn.microsoft.com/en-us/security/', 'free', 'Public Microsoft Learn documentation; no login required.', 'tutorial', 'Microsoft''s security documentation hub covering cloud security, identity, posture management, defender tooling and secure development guidance.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-050', 'Study guide for Exam SC-900: Microsoft Security, Compliance, and Identity Fundamentals', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Beginner', 10, 'English', 'https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-900', 'free', 'Public study guide; no login required.', 'tutorial', 'Official SC-900 study guide covering security, compliance and identity concepts: defence in depth, Zero Trust, shared responsibility, governance and compliance.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-051', 'Describe Security Concepts and Methodologies - Training | Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Beginner', 8, 'English', 'https://www.learn.microsoft.com/en-us/training/modules/describe-security-concepts-methodologies/', 'free', 'Public Microsoft Learn module; no login required.', 'course', 'Learning module on core security concepts and methodologies: CIA triad, defence in depth, Zero Trust, encryption, hashing, digital signatures and the CIA and NIST frameworks.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-052', 'Introduction to Microsoft security solutions - Training | Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Beginner', 12, 'English', 'https://learn.microsoft.com/en-us/training/paths/describe-capabilities-of-microsoft-security-solutions', 'free', 'Public Microsoft Learn learning path; no login required.', 'learning_path', 'Learning path introducing the Microsoft security solution portfolio: Defender, Sentinel, Entra ID, Defender for Cloud and how the pieces combine in an enterprise estate.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-053', 'Manage identity and access in Microsoft Entra ID - Training | Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cloud', 'Intermediate', 16, 'English', 'https://learn.microsoft.com/en-us/training/paths/manage-identity-and-access/', 'free', 'Public Microsoft Learn learning path; no login required.', 'learning_path', 'Learning path on managing identity and access in a cloud directory: authentication methods, conditional access, role-based access, privileged identity and governance.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-054', 'Computer Systems Security | MIT OpenCourseWare', 'MIT OpenCourseWare', 'https://ocw.mit.edu/', 'Cybersecurity', 'Advanced', 80, 'English', 'https://ocw.mit.edu/courses/6-858-computer-systems-security-fall-2014/', 'free', 'Free course materials on MIT OpenCourseWare; no login required.', 'course', 'MIT graduate course on computer systems security: operating system protection, network security, trusted computing, applied cryptography and system-level threat analysis.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-055', 'Readings | Computer Systems Security | MIT OpenCourseWare', 'MIT OpenCourseWare', 'https://ocw.mit.edu/', 'Cybersecurity', 'Advanced', 40, 'English', 'https://ocw.mit.edu/courses/6-858-computer-systems-security-fall-2014/pages/readings/', 'free', 'Free course materials on MIT OpenCourseWare; no login required.', 'course', 'Reading list and lecture notes for the MIT computer systems security course, organised by topic: protection mechanisms, network attacks, runtime attacks and applied cryptography.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-056', 'Introduction to Computer Science and Programming in Python | MIT OpenCourseWare', 'MIT OpenCourseWare', 'https://ocw.mit.edu/', 'Cybersecurity', 'Beginner', 60, 'English', 'https://ocw.mit.edu/courses/6-0001-introduction-to-computer-science-and-programming-in-python-fall-2016/', 'free', 'Free course materials on MIT OpenCourseWare; no login required.', 'course', 'MIT''s introductory Python course teaching programming fundamentals, which underpins the scripting and automation work security analysts do with Python and Bash.', true, '2026-10-30T00:00:00Z'),
  ('hls-sec-057', 'Nmap Network Scanning - The Official Nmap Project Guide to Network Discovery and Security Scanning', 'The Nmap Project', 'https://nmap.org/', 'Cybersecurity', 'Intermediate', 20, 'English', 'https://nmap.org/book/', 'free', 'Publicly available official Nmap guide; no login required.', 'course', 'The official Nmap book: installation, host discovery, port and version scanning, OS detection, Nmap scripting and the network discovery methodology behind security assessments.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-002', 'What is IAM? - AWS Identity and Access Management', 'Amazon Web Services (AWS)', 'https://aws.amazon.com/', 'Cloud', 'Beginner', 8, 'English', 'https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html', 'free', 'Public AWS documentation; no login required.', 'tutorial', 'AWS documentation introducing identity and access management: principals, policies, roles, least privilege, federation and access analysis.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-003', 'Wireshark Documentation', 'Wireshark Foundation', 'https://www.wireshark.org/', 'Cybersecurity', 'Intermediate', 12, 'English', 'https://www.wireshark.org/docs/', 'free', 'Public project documentation; no login required.', 'tutorial', 'Wireshark''s official documentation and user guide covering capture, protocol analysis, display filters, tshark and the practical work of network traffic investigation.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-004', 'What is Microsoft Sentinel SIEM?', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Cybersecurity', 'Beginner', 8, 'English', 'https://learn.microsoft.com/en-us/azure/sentinel/overview', 'free', 'Public Microsoft Learn documentation; no login required.', 'tutorial', 'Microsoft''s Sentinel documentation hub describing the cloud SIEM: data connectors, analytics and detection rules, investigations, automation and incident response.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-005', 'Excel help & learning | Microsoft Support', 'Microsoft Support', 'https://support.microsoft.com/', 'Compliance', 'Beginner', 10, 'English', 'https://support.microsoft.com/en-us/excel/', 'free', 'Public support and learning site; no login required.', 'tutorial', 'Microsoft''s public Excel learning and support hub covering formulas, data cleaning, pivot tables, lookups and the spreadsheet analysis used in control testing and reporting.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-006', 'Power BI documentation - Power BI | Microsoft Learn', 'Microsoft Learn', 'https://learn.microsoft.com/', 'Compliance', 'Intermediate', 20, 'English', 'https://learn.microsoft.com/en-us/power-bi/', 'free', 'Public Microsoft Learn documentation; no login required.', 'tutorial', 'Power BI''s documentation hub covering data modelling, DAX, reports, dashboards, dataflows and the governance and auditing features used for compliance reporting.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-007', 'Confluence: AI Workspace for Knowledge & Collaboration', 'Atlassian', 'https://www.atlassian.com/', 'Compliance', 'Beginner', 6, 'English', 'https://www.atlassian.com/software/confluence', 'free', 'Vendor''s public product page; no login required.', 'tutorial', 'Atlassian''s public overview of Confluence, the knowledge and project workspace used to publish client findings, policies and engagement documentation.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-008', 'Trailhead | The fun way to learn', 'Salesforce', 'https://www.salesforce.com/', 'Business', 'Beginner', 12, 'English', 'https://trailhead.salesforce.com/', 'free', 'Public learning platform; no login required to browse the modules.', 'learning_path', 'Salesforce Trailhead''s free learning platform covering CRM, contract and quote management, approval flows and the Salesforce administration a contract manager works with.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-010', 'Semgrep Documentation', 'Semgrep', 'https://semgrep.dev/', 'Cybersecurity', 'Intermediate', 8, 'English', 'https://semgrep.dev/docs/', 'free', 'Vendor''s public product site; no login required.', 'tutorial', 'Semgrep documentation: static analysis rules, writing custom rules, scanning code and integrating findings into delivery pipelines.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-011', 'Snyk Developer Documentation', 'Snyk', 'https://snyk.io/', 'Cybersecurity', 'Intermediate', 8, 'English', 'https://docs.snyk.io/', 'free', 'Vendor''s public product site; no login required.', 'tutorial', 'Snyk developer documentation: securing code, dependencies, containers and infrastructure as code, and fixing what the scanner finds.', true, '2026-10-30T00:00:00Z'),
  ('hls-x-012', 'Security and code quality documentation - GitHub Docs', 'GitHub', 'https://docs.github.com/', 'Cybersecurity', 'Intermediate', 10, 'English', 'https://docs.github.com/en/code-security', 'free', 'Public product documentation; no login required.', 'tutorial', 'GitHub''s documentation for code security features: code scanning, secret scanning, dependency review and the pull request checks used in secure code review.', true, '2026-10-30T00:00:00Z'),
  ('b-coursera-project-management', 'Foundations of Project Management', 'Coursera', 'https://www.coursera.org', 'Project Management', 'Beginner', 8, 'English', 'https://www.coursera.org/learn/project-management-foundations', 'audit', 'Audit the course free on Coursera; a verified certificate is paid for.', 'course', 'Foundations of Project Management: scoping, planning, scheduling, stakeholder handling and delivering under constraint.', true, '2026-10-30T00:00:00Z'),
  ('b-coursera-business-model', 'Business Model Canvas: A Tool for Entrepreneurs and Innovators (Project-Centered Course)', 'Coursera', 'https://www.coursera.org', 'Business', 'Beginner', 6, 'English', 'https://www.coursera.org/learn/business-model-canvas', 'audit', 'Audit the course free on Coursera; a verified certificate is paid for.', 'course', 'Business Model Canvas: identifying the customer problem, value proposition, channels, revenue model and testing assumptions.', true, '2026-10-30T00:00:00Z')
